glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
#if USE_NOISE_ANIM
  uniform sampler2D secTmpNoiseTexture;
  uniform sampler2D tmpNoiseTexture;
  uniform sampler2D noiseTexture;
  uniform NoiseAnim{
    float speed;
  };
#endif
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_NOISE_ANIM
    vec4 noise = vec4(1,1,1,1);
    vec4 noise_s = vec4(1,1,1,1);
    vec4 noise_t = vec4(1,1,1,1);
    float time = speed*cc_time.x;
    vec2 uv1 = vec2(v_uv0.x-sin(time*0.6+v_uv0.x)*0.05,v_uv0.y+sin(time*0.4+v_uv0.y)*0.05);
    vec2 uv2 = vec2(v_uv0.x+sin(time*1.1+v_uv0.y)*0.02,v_uv0.y+sin(time*0.6+v_uv0.x)*0.09);
    vec2 uv3 = vec2(v_uv0.x+sin(time*0.1+v_uv0.x)*0.02,v_uv0.y-sin(time*0.2+v_uv0.y)*0.03);
  vec4 secTmpNoiseTexture_tmp = texture(secTmpNoiseTexture, uv3);
  #if CC_USE_ALPHA_ATLAS_secTmpNoiseTexture
      secTmpNoiseTexture_tmp.a *= texture(secTmpNoiseTexture, uv3 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    noise_t.rgb *= (secTmpNoiseTexture_tmp.rgb * secTmpNoiseTexture_tmp.rgb);
    noise_t.a *= secTmpNoiseTexture_tmp.a;
  #else
    noise_t *= secTmpNoiseTexture_tmp;
  #endif
  vec4 tmpNoiseTexture_tmp = texture(tmpNoiseTexture, uv2);
  #if CC_USE_ALPHA_ATLAS_tmpNoiseTexture
      tmpNoiseTexture_tmp.a *= texture(tmpNoiseTexture, uv2 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    noise.rgb *= (tmpNoiseTexture_tmp.rgb * tmpNoiseTexture_tmp.rgb);
    noise.a *= tmpNoiseTexture_tmp.a;
  #else
    noise *= tmpNoiseTexture_tmp;
  #endif
  vec4 noiseTexture_tmp = texture(noiseTexture, uv1);
  #if CC_USE_ALPHA_ATLAS_noiseTexture
      noiseTexture_tmp.a *= texture(noiseTexture, uv1 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    noise_s.rgb *= (noiseTexture_tmp.rgb * noiseTexture_tmp.rgb);
    noise_s.a *= noiseTexture_tmp.a;
  #else
    noise_s *= noiseTexture_tmp;
  #endif
    if(noise.x>0.95){
      noise.x = 0.0;
    }
    if(noise_s.x>0.95){
      noise_s.x = 0.0;
    }
    if(noise_t.x>0.95){
      noise_t.x = 0.0;
    }
    o.a = noise_t.x* noise_s.x*noise.x;
    o.a-=0.1;
  #endif
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  o *= v_color;
  ALPHA_TEST(o);
  #if USE_BGRA
    gl_FragColor = o.bgra;
  #else
    gl_FragColor = o.rgba;
  #endif
}

