  #endif
  #if INPUT_IS_GAMMA
    noise.rgb *= (tmpNoiseTexture_tmp.rgb * tmpNoiseTexture_tmp.rgb);
    noise.a *= tmpNoiseTexture_tmp.a;
  #else
    noise *= tmpNoiseTexture_tmp;
  #endif
  vec4 noiseTexture_tmp = texture2D(noiseTexture, uv1);
  #if CC_USE_ALPHA_ATLAS_noiseTexture
      noiseTexture_tmp.a *= texture2D(noiseTexture, uv1 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
